// Long-nurture reminders. Add rows here as needed - date is when Hector wants the nudge.
const REMINDERS = [
  { date: '2027-02-01', who: 'Andrew Ikall',
    phone: '(214) 886-9969', email: 'andrewikall@gmail.com',
    note: '921 Glen Stone Ln. Came in via Meta ads July 2026. Could not sell for ~1 year because of a 1031 exchange, targeting summer 2027. This is the check-in ahead of that window. Ask how the exchange went and whether the timeline still holds.' }
];
const today = new Date().toISOString().slice(0,10);
const due = REMINDERS.filter(r => r.date <= today);
if (!due.length) return [];
const body = due.map(r =>
  r.who + '\n' + r.phone + '  ·  ' + r.email + '\n\n' + r.note
).join('\n\n' + '-'.repeat(46) + '\n\n');
return [{ json: { count: due.length,
  subject: 'Reminder: reach out to ' + due.map(r=>r.who).join(', '),
  body: 'This was set months ago. Time to reconnect.\n\n' + '='.repeat(46) + '\n\n' + body } }];

